def build_pair(doc, p):
    if (False) or (doc is None):
        raise RuntimeError("context and document must not be nil")
    pinionParams = p._copy()
    pinionParams.Teeth, pinionParams.MateTeeth = p.MateTeeth, p.Teeth
    pinionParams.ToeRadius, pinionParams.MateToeRadius = p.MateToeRadius, p.ToeRadius
    pinionParams.BaseHeight, pinionParams.MateBaseHeight = p.MateBaseHeight, p.BaseHeight
    pinionParams.BoreDiameter, pinionParams.MateBoreDiameter = p.MateBoreDiameter, p.BoreDiameter
    drivingPlan = _prepare_build(p)
    pinionPlan = _prepare_build(pinionParams)
    _record_parameters(doc, p)
    if drivingPlan.spiral:
        return _build_spiral_pair(doc, p, pinionParams, drivingPlan, pinionPlan)
    drivingSection = _blank_section_of(drivingPlan.geometry)
    pinionSection = _blank_section_of(pinionPlan.geometry)
    containers = _new_pair_containers(doc)
    shaft = _new_shaft_frame(p.ShaftAngle)
    drivingBlank, pinionBlank = _revolve_shared_blanks(doc, containers.pair, drivingSection, pinionSection, shaft)
    drivingBlank = _move_body(doc, drivingBlank, containers.driving)
    pinionBlank = _move_body(doc, pinionBlank, containers.pinion)
    pinion = _build_member(doc, containers.pinion, shaft, pinionBlank, pinionParams, pinionPlan, True)
    driving = _build_member(doc, containers.driving, _local_shaft, drivingBlank, p, drivingPlan, False)
    if (p.MateTeeth % 2) == 1:
        pinionPhase = _fx.r3_rotation(_shaft_frame_axis(shaft), _fx.units_radians(math.pi / float(p.MateTeeth)))
        pinion = _fx.decad_transform(pinion, pinionPhase, name="Pinion Tooth Phase Turn")
